INSERT INTO alerts (alert_code, scope, centre_id, state, district, alert_type, severity, what, where_location, when_timestamp, why, recommended_action, is_resolved) VALUES
('ALT-CTR-2026-001', 'CENTRE', 'CENTRE-GOA-01', 'Goa', 'North Goa', 'CAPACITY_PREDICTED_EXCEED', 'CRITICAL', 'Yard storage and daily processing capacity predicted to exceed 92% within 48 hours.', 'Sanquelim Krishi Upaj Mandi, North Goa', '2026-10-01 08:30:00', 'Arrival velocity surge from 42 booked farmer lots (1,240 Q) exceeds daily processing gate threshold (800 Q).', 'Activate secondary weighing bay, adjust booking slots, and notify alternative centre CENTRE-GOA-02.', 0),
('ALT-CTR-2026-002', 'CENTRE', 'CENTRE-GOA-01', 'Goa', 'North Goa', 'STORAGE_SHORTAGE', 'HIGH', 'Storage godown stack usage reached 88% capacity (17,600 Q / 20,000 Q).', 'Sanquelim Krishi Upaj Mandi Godown A & B', '2026-10-01 09:15:00', 'Cumulative inward procurement pace over past 5 days has outpaced outward rail/road dispatch by 320 Q/day.', 'Schedule immediate evacuation of 500 Q Paddy buffer to state warehouse or flour mills.', 0),
('ALT-CTR-2026-003', 'CENTRE', 'CENTRE-GOA-01', 'Goa', 'North Goa', 'CONGESTION_ALERT', 'HIGH', 'Gate queue congestion index reached HIGH with 18 tractor trolleys waiting outside Gate 2.', 'North Goa Gate 2 Weighbridge Entrance', '2026-10-01 10:00:00', 'Simultaneous morning slot arrivals combined with a 25-minute calibration delay on Weighbridge WB-01.', 'Deploy traffic marshals to split arrivals between Weighbridge WB-01 and auxiliary platform WB-02.', 0),
('ALT-CTR-2026-004', 'CENTRE', 'CENTRE-GOA-01', 'Goa', 'North Goa', 'TRUCK_SHORTAGE', 'MEDIUM', 'Shortfall of 3 heavy-duty 200Q evacuation trucks for scheduled evening dispatch.', 'Logistics Dispatch Bay 4, Sanquelim', '2026-10-01 11:00:00', 'Transporter fleet delayed on Belagavi-Goa ghat section due to road maintenance.', 'Request emergency transporter re-allotment from Central Logistics Pool or State Agricoop fleet.', 0),
('ALT-CTR-2026-005', 'CENTRE', 'CENTRE-GOA-01', 'Goa', 'North Goa', 'BARDAN_SHORTAGE', 'MEDIUM', 'Bardan (50kg jute bags) stock below 5-day safety buffer (Available: 3,200 bags, Required: 4,800 bags).', 'Inventory Warehouse C, Sanquelim', '2026-10-01 11:30:00', 'Higher-than-expected small-bag packing requests from local paddy cultivators.', 'Requisition 2,000 standard Class-A gunny bags from Mapusa Regional Depot.', 0),
('ALT-CTR-2026-006', 'CENTRE', 'CENTRE-GOA-01', 'Goa', 'North Goa', 'ANOMALY_REVIEW', 'HIGH', 'Potential Anomaly / Requires Review: 45% weight mismatch on procurement lot PRC-CENTRE-GOA-01-0042.', 'Weighbridge Station WB-01, Sanquelim', '2026-10-01 12:15:00', 'Gross weighed quantity (145.0 Q) exceeds pre-registered booking expectation (100.0 Q) by 45%.', 'Conduct mandatory supervisor verification and re-tare empty trolley before approving final receipt.', 0),
('ALT-CTR-2026-007', 'CENTRE', 'CENTRE-GOA-01', 'Goa', 'North Goa', 'PAYMENT_OPERATIONAL_ISSUE', 'MEDIUM', '5 DBT payment records returned IFSC bank validation warnings.', 'Direct DBT Settlement Desk, Sanquelim', '2026-10-01 13:00:00', 'Recent rural cooperative bank IFSC migration to amalgamated national bank code format.', 'Contact cultivators via SMS/agent to confirm updated IFSC branch code before re-submitting DBT batch.', 0),
('ALT-GOV-2026-001', 'GOVERNMENT', NULL, 'Maharashtra', 'Nashik', 'CENTRES_APPROACHING_CAPACITY', 'CRITICAL', '3 Procurement Centres in Nashik district predicted to reach full capacity (>95%) within 72 hours.', 'Niphad, Malegaon & Dindori APMC Hubs, Nashik, Maharashtra', '2026-10-01 09:00:00', 'Coinciding peak harvest arrivals of Soybean and Maize across Godavari canal catchment area.', 'Direct district administration to expand yard overflow godowns and open temporary satellite procurement points.', 0),
('ALT-GOV-2026-002', 'GOVERNMENT', NULL, 'Karnataka', 'Belagavi', 'REGIONAL_STORAGE_SHORTAGE', 'HIGH', 'Belagavi district aggregate warehouse utilization reached 89.4% with 48,000 Q stock.', 'District Food & Civil Supplies Silo Network, Belagavi, Karnataka', '2026-10-01 09:30:00', 'Inter-state procurement inflows from border talukas created unexpected 12,000 Q buffer accumulation.', 'Authorize inter-district rail freight movement of 15,000 Q Maize to deficit coastal feed plants in Goa & Karwar.', 0),
('ALT-GOV-2026-003', 'GOVERNMENT', NULL, 'Maharashtra', 'Nagpur', 'TRUCK_SHORTAGE_REGIONAL', 'HIGH', 'Regional truck deficit of 18 carrier units across Vidarbha cotton procurement belt.', 'Katol, Saoner & Umred Procurement Centres, Nagpur, Maharashtra', '2026-10-01 10:15:00', 'High volume cotton bale dispatch demand exceeding registered district transport contractor capacity.', 'Issue state transport pool mobilization order; divert 20 idle carrier trucks from Wardha corridor.', 0),
('ALT-GOV-2026-004', 'GOVERNMENT', NULL, 'Madhya Pradesh', 'Indore', 'CONGESTION_HOTSPOT', 'CRITICAL', 'Congestion hotspot developing at Sanwer & Indore Krishi Upaj Mandis: Average processing latency > 4.5 hours.', 'Malwa Plateau Procurement Corridor, Madhya Pradesh', '2026-10-01 10:45:00', 'Soybean arrival influx concentrated between 09:00 AM - 12:00 PM due to weather forecast fears.', 'Enforce staggered slot schedules and advise farmers in Mhow & Depalpur to redirect to Ujjain sub-yards.', 0),
('ALT-GOV-2026-005', 'GOVERNMENT', NULL, 'Goa', 'North Goa', 'SUPPLY_DEFICIT_WARNING', 'HIGH', 'State-level Maize feed supply deficit projected at -4,800 Q against poultry processing demand.', 'Statewide Food & Poultry Feed Supply Directorate, Goa', '2026-10-01 11:30:00', 'Local production fulfills only 62% of feed mill commitments; seasonal imports from Belagavi delayed.', 'Facilitate expedited inter-state green corridor transit for incoming grain carriers from Chikkodi Mandi.', 0),
('ALT-GOV-2026-006', 'GOVERNMENT', NULL, 'Maharashtra', 'Kolhapur', 'PERISHABLE_TRANSPORT_RISK', 'CRITICAL', 'High-priority Perishable Sugarcane transport bottleneck: 1,400 Q cut cane facing crushing delay > 36 hours.', 'Shirol & Karvir Cane Procurement Stations, Kolhapur, Maharashtra', '2026-10-01 12:00:00', 'Sugarcane sucrose inversion risk escalating rapidly; truck turnaround slowed by highway bridge repairs.', 'Assign top green-channel transport priority; re-route cane logistics through bypass arterial route.', 0),
('ALT-GOV-2026-007', 'GOVERNMENT', NULL, 'Goa', 'South Goa', 'ANOMALY_PATTERN_CONCENTRATION', 'HIGH', 'Anomaly Pattern Concentration: 6 repeated moisture threshold deviations flagged in South Goa cluster.', 'Margao and Ponda APMC Sub-Centres, South Goa', '2026-10-01 12:45:00', 'Cluster analysis indicates consistent 16.5% - 18.0% moisture readings from common village dispatch points.', 'Deploy state quality inspection vigilance squad to test moisture meters and inspect farm drying practices.', 0);
